function biMarketV2(){const assets=state.data.projects.map(p=>{const margin=p.budget?Math.round((p.budget-p.cost)/p.budget*100):0,result=p.budget-p.cost,score=Math.max(0,Math.min(100,Math.round(margin*.6+p.progress*.4))),signal=score>=65?'Forte':score>=40?'Atenção':'Crítico';return {...p,margin,result,score,signal}}).filter(p=>state.biMarketFilter==='all'||p.signal===state.biMarketFilter).sort((a,b)=>state.biMarketSort==='result'?b.result-a.result:state.biMarketSort==='margin'?b.margin-a.margin:state.biMarketSort==='progress'?b.progress-a.progress:b.score-a.score);let index=0,html=biMarket().replace(/<article class="market-asset">/g,()=>{const asset=assets[index++];return `<article class="market-asset ${state.biMarketAsset===asset.id?'selected':''}" data-market-asset="${asset.id}">`}),selected=assets.find(p=>p.id===state.biMarketAsset)||null;if(selected)html=html.replace('<section class="market-terminal">','<section class="market-terminal active-detail">').replace('<div class="market-layout">',marketDetail(selected)+'<div class="market-layout">');return html}
