function openCollaboratorProfile(id){const person=state.data.collaborators.find(item=>item.id===id);if(!person)return;const records=(state.data.evaluations||[]).filter(row=>(row.collaborator||row.evaluator)===person.name),scores=collaboratorScores(records),initials=person.name.split(' ').map(part=>part[0]).slice(0,2).join('');const dialog=ensureCollaboratorProfile();dialog.innerHTML=`<section class="dialog-head"><div><p class="eyebrow">PERFIL DO COLABORADOR</p><h2>${person.name}</h2></div><button class="icon-button" data-profile-close aria-label="Fechar">×</button></section><section class="dialog-body"><div class="client-hero"><div class="client-avatar">${initials}</div><div><p>${person.role||'Função a definir'}</p><span>${badge(person.status||'Ativo')}</span></div></div><div class="kpi-grid"><div class="kpi"><div class="kpi-top">Desempenho geral</div><div class="kpi-value">${scores.overall?scores.overall.toFixed(1):'—'}</div><div class="kpi-note">base: ${records.length} avaliação(ões)</div></div><div class="kpi"><div class="kpi-top">Instalação</div><div class="kpi-value">${scores.installation?scores.installation.toFixed(1):'—'}</div><div class="kpi-note">qualidade técnica</div></div><div class="kpi"><div class="kpi-top">Atendimento</div><div class="kpi-value">${scores.service?scores.service.toFixed(1):'—'}</div><div class="kpi-note">experiência do cliente</div></div><div class="kpi"><div class="kpi-top">Compromisso</div><div class="kpi-value">${scores.commitment?scores.commitment.toFixed(1):'—'}</div><div class="kpi-note">execução e prazo</div></div></div><section class="card"><h3>Informações profissionais</h3><dl class="detail-list"><div><dt>Especialidade</dt><dd>${person.specialty||'Não informada'}</dd></div><div><dt>Atuação</dt><dd>${person.relationship||'Não informada'}</dd></div><div><dt>Disponibilidade</dt><dd>${person.availability||'Não informada'}</dd></div><div><dt>Remuneração / acordo</dt><dd>${person.compensation||'Não informado'}</dd></div></dl></section><section class="card"><div class="card-head"><h3>Histórico de avaliações</h3><span class="subtext">${records.length} registro(s)</span></div>${records.length?table(['Data','Fonte','Avaliador','Instalação','Atendimento','Compromisso','Prazo'],records.map(row=>`<tr><td>${row.date||'—'}</td><td>${badge(row.source||'Interna')}</td><td>${row.evaluator||'—'}</td><td>${row.installation}/5</td><td>${row.service}/5</td><td>${row.commitment}/5</td><td>${row.deadline}/5</td></tr>`)):'<p class="subtext">Ainda não há avaliações vinculadas a esta pessoa.</p>'}</section></section><footer class="dialog-actions"><button class="button secondary" data-profile-close>Fechar</button><button class="button primary" data-profile-edit="${person.id}">Editar perfil</button></footer>`;dialog.querySelectorAll('[data-profile-close]').forEach(button=>button.onclick=()=>dialog.close());dialog.querySelector('[data-profile-edit]').onclick=()=>{dialog.close();openForm('collaborator',person.id)};dialog.showModal()}
