function removeCommercialFromAgenda(item){const opportunity=state.data.opportunities.find(o=>o.id===item.id);if(!opportunity)return;if(!confirm(`Remover “${item.title}” da agenda?\n\nA oportunidade comercial será mantida; somente a próxima ação e a data agendada serão removidas.`))return;const before=structuredClone(state.data);opportunity.nextAction='';opportunity.nextDue='';if($('#agendaItemDialog').open)$('#agendaItemDialog').close();if($('#agendaQuickDialog').open)$('#agendaQuickDialog').close();persist();render();offerUndo(`Ação comercial ${item.title} foi removida da agenda.`,before)}
