const quoteStatuses=['Rascunho','Enviado','Aprovado','Recusado','Vencido'];
const quoteStatus=quote=>quote.status==='Em elaboração'||!quote.status?'Rascunho':quote.status;
function quoteRoomTotals(room){return(room.items||[]).reduce((total,item)=>{const product=productById(item.productId);if(!product)return total;const qty=Number(item.qty||0),baseCost=Number(product.cost||0)*qty,basePrice=Number(product.price||0)*qty,discount=Math.max(0,Math.min(100,Number(item.discount||0))),discountValue=basePrice*discount/100;total.cost+=baseCost;total.gross+=basePrice;total.discount+=discountValue;total.price+=basePrice-discountValue;return total},{cost:0,gross:0,discount:0,price:0})}
